/* Componentes dos fluxos; usa os mesmos painéis, tabelas e diálogos do sistema. */
(() => {
  'use strict';
  const W=MSA.workflows;
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const num=v=>Number(v||0).toLocaleString('pt-BR',{maximumFractionDigits:1});
  const stamp=at=>new Date(at).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'medium'});
  let day='',shift='1',alertFilter='abertos';
  const action=(label,name,id='',extra='')=>`<button class="text-button" type="button" data-action="wf-${name}" data-id="${esc(id)}" ${extra}>${esc(label)}</button>`;
  function reasonFields(c,record={}) {
    const found=W.reasons.find(r=>r[0]===record.motivoCodigo||r[1]===record.motivo),value=found?.[0]||(record.motivo?'outro':'');
    return c.select('motivoCodigo','Motivo da parada',[['','Selecione o motivo'],...W.reasons.map(r=>[r[0],r[1]]),['outro','Outro motivo']],value)+`<label class="ops-field full" data-other-reason ${value==='outro'?'':'hidden'}>Outro motivo<input name="motivoOutro" value="${esc(found?'':record.motivo||'')}" maxlength="300" ${value==='outro'?'required':''}></label>`;
  }
  function context(c){if(!day){const t=c.state.demo?{dia:new Date(c.state.scenarioAt).toLocaleDateString('sv'),turno:'1'}:W.shiftAt(Date.now());day=t.dia;shift=t.turno;}return `<div class="ops-toolbar"><label>Dia de produção<input type="date" id="wf-day" value="${day}"></label><label>Turno<select id="wf-shift">${MSA.shifts.definitions.map(t=>`<option value="${t.id}" ${shift===t.id?'selected':''}>${t.label} · ${t.hours}</option>`).join('')}</select></label></div>`;}
  function scoped(c,key){const ids=new Set(c.machines().map(m=>m.id));return (c.state[key]||[]).filter(r=>ids.has(r.maquinaId));}
  function people(c){return c.state.perfis.filter(p=>p.cargo==='operador'&&(c.user.cargo==='chefe'?(c.sector==='todos'||p.setorId===c.sector):p.setorId===c.user.setorId));}
  function log(r){return `<details class="workflow-history"><summary>Histórico</summary>${(r.historico||[]).map(h=>`<p><strong>${esc(W.batchStatus[h.status]||W.alertStatus[h.status]||h.status)}</strong> · ${stamp(h.at)}<small>${esc(h.responsavel)}${h.re?' · RE '+esc(h.re):''}</small>${esc(h.observacao)}</p>`).join('')||'<p>Sem alterações registradas.</p>'}</details>`;}
  function render(area,c){
    const {state:s,table,panel,badge,kpis,machineLink}=c;
    if(area==='micro'){
      const stops=c.records('paradas').filter(r=>r.fim&&r.fim-r.inicio<60000&&r.fim>r.inicio),pending=c.records('paradas').filter(r=>r.automatica&&!r.motivoConfirmado);
      return kpis([['Microparadas',stops.length,'','Interrupções encerradas abaixo de 1 min'],['Tempo em microparadas',num(stops.reduce((n,r)=>n+(r.fim-r.inicio)/1000,0)),'s','Incluído no tempo total de paradas'],['Motivos a classificar',pending.length,'','A liderança seleciona após a retomada'],['Maior reincidência',stops.length?c.machineName([...stops.reduce((map,r)=>map.set(r.maquinaId,(map.get(r.maquinaId)||0)+1),new Map())].sort((a,b)=>b[1]-a[1])[0][0]):'—','','No período filtrado']])+
        panel('Microparadas e classificação',`<p class="ops-note">O registro automático preserva início e fim em segundos. A classificação pode ser feita depois que a máquina retomar.</p>${table(['Máquina','Início / fim','Duração','Motivo','Ação'],[...new Map([...pending,...stops].map(r=>[r.id,r])).values()].map(r=>[machineLink(r.maquinaId),stamp(r.inicio)+'<small>'+(r.fim?stamp(r.fim):'Em andamento')+'</small>',num(((r.fim||s.scenarioAt||Date.now())-r.inicio)/1000)+' s',esc(r.motivo)+(r.classificadoRe?'<small>RE '+esc(r.classificadoRe)+' · '+stamp(r.classificadoEm)+'</small>':''),c.allowed('paradas:gerenciar',r)?action('Selecionar motivo','classify',r.id):'—']),'As interrupções curtas aparecerão aqui.')}`,
        s.demo&&c.allowed('paradas:gerenciar')?action('Demonstrar microparada','micro'):'');
    }
    if(area==='lots'||area==='lot-history'){
      const closed=b=>['liberado','descartado'].includes(b.status),[start,end]=c.bounds(),all=scoped(c,'lotesQualidade');
      const rows=all.filter(b=>area==='lot-history'?closed(b)&&(b.updatedAt||b.createdAt)>=start&&(b.updatedAt||b.createdAt)<end:!closed(b));
      return panel(area==='lots'?'Lotes em avaliação':'Histórico de decisões da Qualidade',`<p class="ops-note">${area==='lots'?'Pendências atuais nas máquinas selecionadas, incluindo lotes de dias anteriores. Um defeito sinaliza o lote inteiro; a Qualidade registra segregação, reinspeção e destino.':'Lotes concluídos no período do filtro. Abra Detalhes e histórico para consultar a avaliação e os responsáveis.'}</p>${table(['Lote / máquina','Quantidade do lote','Situação','Avaliação / destino','Ações'],rows.sort((a,b)=>area==='lot-history'?(b.updatedAt||b.createdAt)-(a.updatedAt||a.createdAt):b.createdAt-a.createdAt).map(b=>[`${esc(b.lote)}<small>${machineLink(b.maquinaId)} · ${esc(b.produto)}</small>`,`${num(b.quantidade)} peças<small>${num(b.refugosIdentificados)} refugos identificados</small>`,badge(W.batchStatus[b.status],b.status==='liberado'?'good':b.status==='descartado'?'danger':'warning'),b.inspecionadas!=null?`${num(b.inspecionadas)} inspecionadas<small>${num(b.liberadas)} liberadas · ${num(b.descartadas)} descartadas</small>`:esc(W.batchStatus[b.status]),`<div class="row-actions">${action('Detalhes e histórico','batch-detail',b.id)}${c.allowed('qualidade:decidir',b)&&!closed(b)?action('Avaliar lote','batch',b.id):''}</div>`]),area==='lots'?'Nenhum lote aguardando decisão neste contexto.':'Nenhuma decisão concluída no período selecionado.')}`);
    }
    if(area==='handover'){
      const controls=context(c),all=scoped(c,'passagensTurno'),rows=all.filter(r=>r.dia===day&&r.turno===shift);
      const pending=new Map();for(const r of all)for(const t of r.pendencias||[])if(!t.done)pending.set(t.id,{...t,maquinaId:r.maquinaId,passagemId:r.id});
      return controls+panel('Pendências entre turnos',table(['Máquina','Pendência','Ação'],[...pending.values()].map(t=>[machineLink(t.maquinaId),esc(t.texto),c.allowed('passagem:gerenciar',{setorId:s.maquinas.find(m=>m.id===t.maquinaId)?.setorId})?action('Concluir pendência','task',t.passagemId,`data-task-id="${esc(t.id)}"`):'—']),'Nenhuma pendência entre turnos.'))+
        panel('Passagem de turno',table(['Máquina / turno','Resumo registrado na entrega','Ações e observações','Entrega / recebimento'],rows.sort((a,b)=>b.createdAt-a.createdAt).map(r=>[machineLink(r.maquinaId)+`<small>${esc(r.dia)} · ${r.turno}º turno</small>`,`${num(r.resumo.aprovadas)} / ${num(r.resumo.planejado)} peças<small>${num(r.resumo.paradaSegundos)} s parados · ${num(r.resumo.refugos)} refugos</small><small>Lotes: ${esc(r.resumo.lotes.join(', ')||'—')}</small><small>Ordens: ${esc(r.resumo.ordens.join(', ')||'—')}</small><details><summary>Problemas e alarmes na entrega</summary><p>${esc([...r.resumo.problemas,...r.resumo.alarmes].join('; ')||'Sem problemas abertos.')}</p></details>`,`${esc(r.acoesRealizadas||'Nenhuma ação informada.')}<small>${esc(r.observacao)}</small>${(r.pendencias||[]).map(t=>`<p>${t.done?'✓':'○'} ${esc(t.texto)}${t.done?`<small>Concluída por ${esc(t.doneBy)} · RE ${esc(t.doneRe)} · ${stamp(t.doneAt)}</small>`:''}</p>`).join('')}`,`<strong>${esc(r.entreguePor)}</strong><small>RE ${esc(r.usuarioRe)} · ${stamp(r.createdAt)}</small>${r.status==='recebida'?`${badge('Recebida','good')}<small>${esc(r.recebidoPor)} · RE ${esc(r.recebidoRe)} · ${stamp(r.recebidoEm)}</small>`:badge('Aguardando recebimento','warning')+(c.allowed('passagem:gerenciar',r)&&r.usuarioId!==c.user.id?action('Confirmar recebimento','receive',r.id):'')}`]),'Registre a entrega desse turno. O resumo será preservado mesmo com novos ciclos.'),c.allowed('passagem:gerenciar')?action('Registrar passagem','handover'):'');
    }
    if(area==='alerts'){
      const all=scoped(c,'atendimentosAlertas'),rows=all.filter(r=>alertFilter==='todos'||r.status!=='resolvido');
      return panel('Acompanhamento dos alertas',`<div class="workflow-filter"><label>Situação<select id="wf-alerts"><option value="abertos" ${alertFilter==='abertos'?'selected':''}>Aguardando conclusão</option><option value="todos" ${alertFilter==='todos'?'selected':''}>Todos, inclusive resolvidos</option></select></label></div>${table(['Alerta / máquina','Destinatário / canal','Situação','Ação / histórico'],rows.sort((a,b)=>b.createdAt-a.createdAt).map(r=>[`${esc(r.tipo)} · ${machineLink(r.maquinaId)}<small>${esc(r.descricao)}</small><small>${stamp(r.createdAt)} · ${r.active?'Condição ativa':'Condição normalizada em '+stamp(r.normalizadoEm||r.updatedAt)}</small><a class="ops-link" href="#${r.route}/${encodeURIComponent(r.maquinaId)}">Abrir origem</a>`,`${esc(r.destinatario)}<small>${esc(r.canal||'Tela do sistema')}</small>`,badge(W.alertStatus[r.status],r.status==='resolvido'?'good':'warning'),`${c.allowed('alertas:gerenciar',r)&&r.status!=='resolvido'?action(r.status==='novo'?'Reconhecer':r.status==='reconhecido'?'Iniciar atendimento':'Concluir atendimento','alert',r.id):''}${log(r)}`]),'Sem alertas pendentes.')}`);
    }
    if(area==='staff'){
      const controls=context(c),profiles=people(c),allocations=profiles.map(p=>({p,a:W.allocation(s,p,day,shift)}));
      const occupied=new Set(s.alocacoes.filter(a=>a.dia===day&&a.turno===shift&&a.presenca==='presente').map(a=>a.maquinaId)),unmanned=c.machines().filter(m=>!occupied.has(m.id));
      return controls+kpis([['Equipe prevista',profiles.length,'','Operadores no contexto'],['Presentes',allocations.filter(({a})=>a.presenca==='presente').length,'','Confirmados pela liderança'],['Ausentes',allocations.filter(({a})=>a.presenca==='ausente').length,'','Redistribuir equipe'],['Presenças a confirmar',allocations.filter(({a})=>a.presenca==='pendente').length,'','Ainda não conferidas nesse turno']])+
        panel('Postos sem equipe confirmada',table(['Máquina / setor','Situação'],unmanned.map(m=>[machineLink(m.id)+'<small>'+esc(c.sectorName(m.setorId))+'</small>',badge('Sem equipe confirmada','warning')]),'Todos os postos têm equipe presente no turno.'))+
        panel('Presença e alocação por turno',table(['Funcionário / RE','Setor de origem','Presença','Posto neste turno','Histórico / ação'],allocations.map(({p,a})=>[`${esc(p.nome)}<small>RE ${esc(p.re)}</small>`,esc(c.sectorName(p.setorId)),badge({presente:'Presente',ausente:'Ausente',pendente:'A confirmar'}[a.presenca],a.presenca==='presente'?'good':'warning'),a.maquinaId?machineLink(a.maquinaId)+'<small>'+esc(c.sectorName(a.setorDestino||a.setorId))+'</small>':'Sem posto',`${c.allowed('funcionarios:atribuir',{setorId:p.setorId})?action('Confirmar / redistribuir','staff',p.id):''}${log(a)}`])))+
        '<p class="ops-note">Presença e distribuição são confirmadas pela liderança. O histórico do turno e os apontamentos anteriores preservam o RE e a máquina de origem.</p>';
    }
    return '';
  }
  function summaryPreview(c){const host=document.querySelector('[data-handover-preview]');if(!host)return;try{const f=c.form.elements,x=W.handoverSummary(c.state,f.maquinaId.value,f.dia.value,f.turno.value);host.textContent=`Resumo automático: ${num(x.aprovadas)} / ${num(x.planejado)} peças; ${num(x.paradaSegundos)} s de parada; ${num(x.refugos)} refugos. Lotes: ${x.lotes.join(', ')}. ${x.problemas.length+x.alarmes.length} problemas / alarmes em aberto.`;}catch(e){host.textContent=e.message;}}
  async function handle(name,id,c,target){
    const s=c.state,choose=c.machines().map(m=>[m.id,m.id+' · '+m.nome]),run=(action,v={},key=id)=>MSA.data.workflow(action,v,key);
    if(name==='wf-batch-detail'){
      const b=s.lotesQualidade.find(b=>b.id===id);if(!b||!MSA.rbac.inScope(c.user,b))throw new Error('Lote indisponível neste acesso.');
      return c.open('Detalhes do lote · '+b.lote,`<section class="full"><dl class="profile-details"><dt>Máquina</dt><dd>${c.machineLink(b.maquinaId)}</dd><dt>Produto</dt><dd>${esc(b.produto)}</dd><dt>Quantidade</dt><dd>${num(b.quantidade)} peças · ${num(b.refugosIdentificados)} refugos identificados</dd><dt>Situação</dt><dd>${esc(W.batchStatus[b.status])}</dd><dt>Motivo inicial</dt><dd>${esc(b.motivo)}</dd><dt>Avaliação / destino</dt><dd>${esc(b.destino||'Aguardando avaliação')}</dd>${b.inspecionadas!=null?`<dt>Reinspeção</dt><dd>${num(b.inspecionadas)} inspecionadas · ${num(b.liberadas)} liberadas · ${num(b.descartadas)} descartadas</dd>`:''}</dl>${log(b).replace('<details','<details open')}</section>`,null);
    }
    if(name==='wf-classify'){const r=s.paradas.find(r=>r.id===id);return c.open('Classificar parada',reasonFields(c,r),v=>run('classify-stop',v));}
    if(name==='wf-micro')return c.open('Demonstrar microparada',c.select('maquinaId','Máquina',choose,choose[0]?.[0])+c.select('segundos','Duração',[['8','8 segundos'],['15','15 segundos'],['30','30 segundos']], '15')+'<p class="ops-form-note">A máquina pausa e retoma automaticamente. Depois, selecione o motivo em Paradas.</p>',v=>MSA.demo.simulation.microStop(v.maquinaId,Number(v.segundos)));
    if(name==='wf-handover'){
      context(c);c.open('Registrar passagem de turno',c.select('maquinaId','Máquina',choose,choose[0]?.[0])+c.field('dia','Dia de produção',day,'date','required')+c.select('turno','Turno',MSA.shifts.definitions.map(t=>[t.id,t.label]),shift)+'<p class="ops-form-note" data-handover-preview></p>'+c.field('acoesRealizadas','Ações realizadas','','textarea')+c.field('pendencias','Novas pendências (uma por linha)','','textarea')+c.field('observacao','Observações para o próximo turno','','textarea'),v=>run('handover-create',v));summaryPreview(c);return;
    }
    if(name==='wf-receive')return c.open('Confirmar recebimento','<p class="ops-form-note">A confirmação registra seu nome, RE e horário como responsável pelo recebimento.</p>',()=>run('handover-receive'));
    if(name==='wf-task')return run('handover-task',{taskId:target.dataset.taskId});
    if(name==='wf-batch'){
      const b=s.lotesQualidade.find(r=>r.id===id),options={suspeito:[['segregado','Confirmar segregação na área vermelha']],segregado:[['reinspecao','Iniciar reinspeção']],reinspecao:[['liberado','Liberar peças conformes e descartar rejeitadas'],['descartado','Destinar lote inteiro ao descarte']]}[b.status];
      return c.open('Avaliar lote · '+b.lote,`<p class="ops-form-note">${num(b.quantidade)} peças no lote · ${num(b.refugosIdentificados)} refugos identificados. Decisão exclusiva da Qualidade.</p>`+c.select('status','Próxima etapa',options,options[0][0])+(b.status==='reinspecao'?c.field('inspecionadas','Peças reinspecionadas',b.quantidade,'number','min="0" step="1" required')+c.field('descartadas','Total de peças destinadas ao descarte',b.refugosIdentificados,'number','min="0" step="1" required'):'')+c.field('observacao','Avaliação / local de segregação / destino','','textarea','required'),v=>run('batch-transition',v));
    }
    if(name==='wf-alert'){const r=s.atendimentosAlertas.find(r=>r.id===id),next={novo:'reconhecido',reconhecido:'atendimento',atendimento:'resolvido'}[r.status];return c.open(W.alertStatus[next]+' · '+r.tipo,`<p class="ops-form-note">${esc(r.descricao)} · ${esc(r.destinatario)}${r.active&&next==='resolvido'?' · A condição de origem ainda está ativa.':''}</p>`+c.field('observacao',next==='reconhecido'?'Observação (opcional)':'Ação realizada / conclusão','','textarea',next==='reconhecido'?'':'required'),v=>run('alert-transition',{...v,status:next}));}
    if(name==='wf-staff'){
      context(c);const p=s.perfis.find(p=>p.id===id),a=W.allocation(s,p,day,shift);
      return c.open('Confirmar presença / redistribuir',`<p class="ops-form-note">${esc(p.nome)} · RE ${esc(p.re)} · ${esc(day)} · ${shift}º turno</p>`+c.select('presenca','Presença',[['pendente','A confirmar'],['presente','Presente'],['ausente','Ausente']],a.presenca)+c.select('maquinaId','Posto de trabalho',[['','Sem posto'],...choose],a.maquinaId,false)+c.field('observacao','Motivo da redistribuição / observação','','textarea'),v=>run('staff-save',{...v,funcionarioId:id,dia:day,turno:shift}));
    }

  }
  function change(event,c){const v=event.target.value;if(event.target.id==='wf-day')day=v;if(event.target.id==='wf-shift')shift=v;if(event.target.id==='wf-alerts')alertFilter=v;}
  function formChange(event,c){if(event.target.name==='motivoCodigo'){const host=document.querySelector('[data-other-reason]'),other=event.target.value==='outro';if(host){host.hidden=!other;host.querySelector('input').required=other;}}
    if(event.target.name==='presenca'&&event.target.value==='ausente')c.form.elements.maquinaId.value='';
    if(['maquinaId','dia','turno'].includes(event.target.name))summaryPreview(c);
  }
  MSA.workflowUI={render,handle,change,formChange,reasonFields};
})();
